async function main() {
  let opts;
  try {
    opts = parseArgs(process.argv.slice(2));
  } catch (err) {
    process.stderr.write(`gandalf-run: ${err.message}\n${USAGE}\n`);
    process.exitCode = 2;
    return;
  }
  if (opts.help) {
    process.stdout.write(`${USAGE}\n`);
    return;
  }

  // W4: the SCALED-GANDALF analyze mode — actually invoke scout + map-reduce over a codebase, routed
  // by context size (single frontier pass for a small target; shard→scout→map→reduce for a large one).
  const started = new Date().toISOString();
  const t0 = Date.now();

  if (opts.analyze) {
    try {
      await runAnalyzeMode(opts);
      writeRunRecord({
        tier: 'scaled-analyze', started, ended: new Date().toISOString(),
        input: `--project ${opts.project || process.cwd()} --objective ${JSON.stringify(opts.objective || '(default)')}`,
        params: { mode: 'analyze' },
        output: opts.output || '(stdout)',
        result: 'analyze completed (see degraded stamp in the report)',
        cross_model: false, models: null, duration_s: Math.round((Date.now() - t0) / 1000), journal_ref: null,
      });
    } catch (err) {
      process.stderr.write(`gandalf-run: --analyze failed — no output written.\n${err.message}\n`);
      process.exitCode = 1;
    }
    return;
  }

  // Read the ARTIFACT under analysis. (2026-07-11: the old grade-mode "router" pass is
  // DELETED — it token-sized the draft JSON, logged model choices, and mutated
  // GEMINI_MODEL/TRIO_MODEL env in a mode that makes zero model calls: pure ceremony
  // with a misleading log and an env side effect. --analyze keeps the real router.)
  let rawText;
  try {
    rawText = opts.input ? readFileSync(opts.input, 'utf8') : readStdin();
  } catch (err) {
    process.stderr.write(`gandalf-run: could not read input: ${err.message}\n`);
    process.exitCode = 2;
    return;
  }

  let output, dispatch = null;
  try {
    if (opts.live) {
      // C1: the LIVE cross-family path — refuters via agy, commissions minted into the
      // shared ledger, cross_model/GROUNDED derived by the gate. HALTs honestly if agy
      // is down (the seam throws; we write NOTHING and exit non-zero).
      const live = await runHostLive(rawText, {
        cross_model: true,
        budget: opts.budget ?? undefined,
        log: (m) => process.stderr.write(`${m}\n`),
      });
      output = live.output;
      dispatch = live.dispatch;
      const minted = dispatch.filter((d) => d.minted).length;
      process.stderr.write(`gandalf-run: --live dispatched ${dispatch.length} refuter(s), ${minted} commission(s) minted\n`);
    } else {
      output = runHost(rawText, { cross_model: opts.cross_model });
    }
  } catch (err) {
    // HONEST failure: malformed draft or a live-path error. Write NOTHING. Label revised
    // 2026-08-25 (journal 0300, rule 9): the old blanket "(agy down / non-attested)" branded
    // EVERY live error a substrate failure — twice misdiagnosing a budget stop as "agy down".
    // Read err.message; it names the actual cause. (Budget excess no longer halts at all —
    // it pre-flights and floors; see live-refuter.mjs.)
    const kind = err instanceof SeamPassInputError ? 'malformed raw draft'
      : opts.live ? `live refutation failed — ${err?.name || 'error'} (read the message below; NOT necessarily agy)` : 'conformance failure';
    process.stderr.write(`gandalf-run: ${kind} — no output written.\n${err.message}\n`);
    process.exitCode = 1;
    return;
  }

  const serialized = `${JSON.stringify(output, null, 2)}\n`;
  if (opts.output) {
    try {
      writeFileSync(opts.output, serialized, 'utf8');
    } catch (err) {
      process.stderr.write(`gandalf-run: could not write output: ${err.message}\n`);
      process.exitCode = 2;
      return;
    }
  } else {
    process.stdout.write(serialized);
  }

  writeRunRecord({
    tier: opts.live ? 'live-cross-family' : 'tier1-deterministic',
    started, ended: new Date().toISOString(),
    input: opts.input || '(stdin)',
    // P0 2026-07-25 (journal 0276): --live hardcodes cross_model:true into runHostLive, so the
    // intent stamp must reflect it — recording opts.cross_model alone stamped intent:false on
    // every --live run, corrupting the training feed for the highest-value runs.
    params: { live: opts.live, budget: opts.budget, cross_model_intent: !!(opts.live || opts.cross_model) },
    output: opts.output || '(stdout)',
    result: `graded: ${Array.isArray(output?.elevations) ? output.elevations.length : 0} elevation(s)` +
      (dispatch ? `; refuters ${dispatch.length}, minted ${dispatch.filter((d) => d.minted).length}` : ''),
    cross_model: output?.cross_model ?? false,
    models: null,
    duration_s: Math.round((Date.now() - t0) / 1000),
    journal_ref: null,
  });
}

export function parseArgs(argv) {
  const opts = {
    input: null,
    output: null,
    cross_model: false,
    project: null,
    analyze: false,
    objective: null,
    live: false,
    budget: null,
    depth: null,
    tier: null,
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--input' || a === '-i') {
      opts.input = argv[++i];
      if (opts.input === undefined) throw new Error('--input requires a file path');
    } else if (a === '--output' || a === '-o') {
      opts.output = argv[++i];
      if (opts.output === undefined) throw new Error('--output requires a file path');
    } else if (a === '--project' || a === '-p') {
      opts.project = argv[++i];
      if (opts.project === undefined) throw new Error('--project requires a directory path');
    } else if (a === '--objective' || a === '-q') {
      opts.objective = argv[++i];
      if (opts.objective === undefined) throw new Error('--objective requires a text argument');
    } else if (a === '--analyze') {
      opts.analyze = true; // Scaled-Gandalf map-reduce mode (route by CONTEXT SIZE over a codebase)
    } else if (a === '--live') {
      // C1 (2026-07-11): the LIVE cross-family path IS now CLI-reachable — the
      // always/stakes-gated cross-model rule stops requiring ad-hoc import glue.
      opts.live = true;
    } else if (a === '--budget') {
      const n = Number(argv[++i]);
      if (!Number.isInteger(n) || n < 1) throw new Error('--budget requires a positive integer');
      opts.budget = n;
    } else if (a === '--depth') {
      opts.depth = argv[++i];
      if (opts.depth === undefined) throw new Error('--depth requires LITE|FULL|SPIKE-FIRST');
    } else if (a === '--tier') {
      opts.tier = argv[++i];
      if (opts.tier === undefined) throw new Error('--tier requires Heavy|Standard');
    } else if (a === '--cross-model') {
      opts.cross_model = true; // INTENT only — the output stamp is DERIVED, never set by this flag
    } else if (a === '--help' || a === '-h') {
      opts.help = true;
    } else {
      throw new Error(`unknown argument ${JSON.stringify(a)}`);
    }
  }
  return opts;
}

function invokedDirectly() {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    const canon = (p) => {
      const abs = resolve(p);
      let real = abs;
      try { real = realpathSync(abs); } catch { /* keep abs (file may be a virtual path) */ }
      return process.platform === 'win32' ? real.toLowerCase() : real;
    };
    return canon(fileURLToPath(import.meta.url)) === canon(entry);
  } catch {
    return false;
  }
}

export function collectProjectPayload(projectDir) {
  const patterns = getGitignorePatterns(projectDir);
  const out = [];
  const walk = (dir) => {
    let entries;
    try { entries = readdirSync(dir); } catch { return; }
    for (const name of entries) {
      const full = join(dir, name);
      const rel = relative(projectDir, full);
      let st;
      try { st = statSync(full); } catch { continue; }
      if (st.isDirectory()) {
        if (isIgnored(rel, patterns, true)) continue;
        walk(full);
      } else if (st.isFile()) {
        if (isIgnored(rel, patterns, false)) continue;
        out.push(rel.replace(/\\/g, '/'));
      }
    }
  };
  walk(projectDir);
  return out;
}

export async function runScaledAnalysis({
  projectDir = null,
  payload,
  userObjective,
  env = process.env,
  log = () => {},
  makeAgent = null,
  highContextLimit = null,
  concurrencyLimit = 3,
  depth = null,
  tier = null,
  maxShards = null,
  fusionPasses = null,
  /** Optional inject for hermetic E1–E4 call-object capture (production omits → live runMapReduce). */
  mapReduceRunner = null,
} = {}) {
  // B2 L2: locked path forwards authoritative band knobs; unlocked keeps caller caps / null.
  // Caller maxShards/fusionPasses cannot invert a lock (unlock-only override).
  const consume = resolveConsumeKnobs({
    depth,
    tier,
    env,
    maxShards,
    fusionPasses,
    userObjective,
  });
  const shards = consume.maxShards;
  const fusions = consume.fusionPasses;
  if (consume.locked) {
    log(`gandalf band: depth=${consume.knobs?.depth} shards=${shards} fusionPasses=${fusions} source=${consume.source}`);
  }

  const { mapModel, reduceModel, mapDriver, reduceDriver } = resolveScaledModels(env);
  const target = projectDir || process.cwd();
  const factory = makeAgent || ((model, role) => {
    const driver = role === 'reduce' ? reduceDriver : mapDriver;
    // Gemini seats keep the dedicated agy seam; all other families use the prefs-routed runAgent.
    if (driver === 'gemini-cli' || String(driver).startsWith('gemini')) {
      return makeGeminiCliSeam({ model, role, env, target, log }).agent;
    }
    return (prompt, opts = {}) => runAgent({
      prompt,
      schema: opts.schema,
      label: opts.label || `gandalf:${role}`,
      role: opts.role || role,
      model: model || opts.model || null,
      driver,
      env: { ...env, CRUCIBLE_AGENT_LIVE: env.CRUCIBLE_AGENT_LIVE || '1' },
      target,
      log,
    });
  });
  const mapAgent = factory(mapModel, 'map');       // REVIEW_FAMILY bulk reads
  const reduceAgent = factory(reduceModel, 'reduce'); // CODING_FAMILY synthesis
  const invokeMapReduce = typeof mapReduceRunner === 'function' ? mapReduceRunner : runMapReduce;
  return invokeMapReduce({
    projectDir,
    payload,
    userObjective,
    env,
    log,
    agent: mapAgent,
    reduceAgent,
    highContextLimit,
    concurrencyLimit,
    maxShards: shards,
    fusionPasses: fusions,
  });
}

export function resolveConsumeKnobs({
  depth = null,
  tier = null,
  env = process.env,
  maxShards = null,
  fusionPasses = null,
  userObjective = '',
} = {}) {
  if (!isGandalfBandLocked({ depth, tier, env })) {
    return {
      locked: false,
      maxShards: maxShards == null ? null : maxShards,
      fusionPasses: fusionPasses == null ? null : fusionPasses,
      knobs: null,
      source: null,
    };
  }
  const band = resolveGandalfBand({
    depth,
    tier,
    intake: { intent: userObjective, scope: depth === 'LITE' ? 'small' : 'large' },
    allowDefault: true,
    env,
  });
  // L4/L5 safety floor: refuse locked band-thin that zeros or omits seats.
  assertGandalfSeatsFloor(band.knobs);
  // Lock wins: never let caller maxShards/fusionPasses invert locked knobs (L2).
  const shards = band.knobs?.shards ?? null;
  const fusions = band.knobs?.fusionPasses ?? null;
  return {
    locked: true,
    maxShards: shards,
    fusionPasses: fusions,
    knobs: band.knobs ?? null,
    source: band.source ?? null,
  };
}

export function resolveScaledModels(env = process.env) {
  const families = loadModelFamilies(env);
  const mapDriver = familyToDriverName(families.review) || 'gemini-cli';
  const reduceDriver = familyToDriverName(families.coding) || 'claude';
  let mapModel = null;
  let reduceModel = null;
  if (mapDriver === 'gemini-cli' || mapDriver.startsWith('gemini')) {
    mapModel = resolveGeminiModel({ env: { ...env, TRIO_TIER: 'standard' } });
  }
  if (reduceDriver === 'gemini-cli' || reduceDriver.startsWith('gemini')) {
    reduceModel = resolveGeminiModel({ env: { ...env, TRIO_TIER: 'heavy' } });
  }
  return { mapModel, reduceModel, mapDriver, reduceDriver, families };
}

export function gradeScaledReport(report) {
  const text = String(report);
  let rawDraft = null;
  try {
    const parsed = JSON.parse(text);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) rawDraft = parsed;
  } catch { /* prose report — wrap it */ }
  if (!rawDraft) {
    rawDraft = {
      reasoning: text,
      verdict: 'scaled analyze — see reasoning (map-reduce advisory prose, host-graded)',
      findings: [],
      nitpicks: [],
      elevations: [],
    };
  }
  const output = runHost(JSON.stringify(rawDraft), { cross_model: false });
  // Carry the map-reduce degradation stamp forward — never silently dropped.
  output.degraded = true;
  const stamp = report && typeof report === 'object' && 'stamp' in report ? report.stamp : null;
  if (stamp) output.scaled_stamp = String(stamp);
  return output;
}

export function runHost(rawText, { cross_model = false, resolveCommission } = {}) {
  let rawDraft;
  try {
    rawDraft = JSON.parse(rawText);
  } catch (err) {
    throw new SeamPassInputError(`the input is not valid JSON: ${err.message}`);
  }
  // W2b: `cross_model` here is the caller INTENT flag only; the output stamp is DERIVED inside
  // applySeamPass from genuine ledger-bound refutations. `resolveCommission` defaults (inside
  // applySeamPass) to the real commission-ledger resolver so the gate is ACTIVE in a real run; a
  // test may inject a stub. We thread `undefined` through untouched so that default applies.
  const output = applySeamPass(rawDraft, { cross_model, resolveCommission });
  // The host's guarantee: never emit anything the canary set would reject. The seam pass is
  // conformant by construction for well-shaped items, but a real cross-model/fused draft can still
  // carry ONE item that trips the canary — degrade to the largest conformant subset (honestly
  // stamped) instead of losing the entire read.
  try {
    assertIncrement1Conformant(output);
    return output;
  } catch (err) {
    if (err instanceof SeamPassInputError) throw err;
    return degradeToConformant(rawDraft, { cross_model, resolveCommission, reason: err.message });
  }
}

export async function runHostLive(rawText, {
  cross_model = false,
  agent,
  ledger: injectedLedger,
  routes,
  drafterFamily,
  refuterFamily = REFUTER_FAMILY,
  budget,
  log = () => {},
} = {}) {
  let rawDraft;
  try {
    rawDraft = JSON.parse(rawText);
  } catch (err) {
    throw new SeamPassInputError(`the input is not valid JSON: ${err.message}`);
  }
  // INVARIANT 1: ONE shared per-run ledger for BOTH the minter and the gate.
  const ledger = injectedLedger || createCommissionLedger();
  const resolveCommission = ledger.resolveCommission;
  // Live agent: omit routes/drafter → coding/review family prefs; tests pass explicit pins.
  const theAgent = agent || (await buildLiveRefuterAgent({ routes, drafterFamily, env: process.env }));

  // Dispatch the live refuters and mint claim-bound commissions into the shared ledger.
  const { draft, dispatch } = await runLiveRefutation(rawDraft, {
    agent: theAgent, ledger, routes, drafterFamily, refuterFamily, budget, log,
  });

  // Grade the refuted draft against the SAME ledger's resolver — cross_model / GROUNDED are DERIVED here.
  const output = applySeamPass(draft, { cross_model, resolveCommission });
  const finalized = finalizeConformant(draft, output, { cross_model, resolveCommission });
  return { output: finalized, dispatch, ledger };
}

function degradeToConformant(rawDraft, { cross_model, resolveCommission, reason }) {
  const firstLine = String(reason || 'conformance failure').split('\n')[0];
  const note =
    `\n\n[gandalf-host] Grading degraded: the full draft tripped a conformance canary (${firstLine}); ` +
    `the read was salvaged to the largest conformant subset (the reasoning narrative above is intact).`;
  const base = { ...rawDraft, reasoning: String(rawDraft.reasoning || '') + note, degraded: true };
  const findings = Array.isArray(base.findings) ? base.findings.slice() : [];
  const nitpicks = Array.isArray(base.nitpicks) ? base.nitpicks.slice() : [];
  const elevations = Array.isArray(base.elevations) ? base.elevations.slice() : [];

  // 1) P0 2026-07-25 (journals 0276/0277): the common case is ONE offending item —
  //    drop just IT and preserve every other finding, elevation, and nitpick. The old
  //    ladder sacrificed the ENTIRE elevations+nitpicks forward layer as its FIRST step,
  //    which almost always conformed — so any single canary trip silently cost the whole
  //    recommendation layer (deterministic, byte-identical, observed live twice on
  //    --live runs; the expensive path returned strictly less advice than the cheap one).
  let out;
  for (const [legName, leg] of [['nitpicks', nitpicks], ['elevations', elevations], ['findings', findings]]) {
    for (let i = 0; i < leg.length; i++) {
      out = tryGrade({ ...base, [legName]: leg.filter((_, j) => j !== i) }, cross_model, resolveCommission);
      if (out) return out;
    }
  }
  // 1b) multiple offenders in ONE forward leg (e.g. an over-cap overrun by >1): shrink
  //     that leg from the tail while keeping the other legs whole.
  for (const [legName, leg] of [['nitpicks', nitpicks], ['elevations', elevations]]) {
    for (let keep = leg.length - 2; keep >= 0; keep--) {
      out = tryGrade({ ...base, [legName]: leg.slice(0, keep) }, cross_model, resolveCommission);
      if (out) return out;
    }
  }
  // 2) cross-leg offenders: drop whole legs in INCREASING-value order — nitpicks, then
  //    elevations, then both. (This was the old step 1; it is now a late resort.)
  out = tryGrade({ ...base, nitpicks: [] }, cross_model, resolveCommission);
  if (out) return out;
  out = tryGrade({ ...base, elevations: [] }, cross_model, resolveCommission);
  if (out) return out;
  out = tryGrade({ ...base, nitpicks: [], elevations: [] }, cross_model, resolveCommission);
  if (out) return out;
  // 3) the offending FINDING cases (with the forward legs already sacrificed):
  //    single offender, then a shrinking prefix (multiple/interacting offenders).
  for (let i = 0; i < findings.length; i++) {
    out = tryGrade({ ...base, findings: findings.filter((_, j) => j !== i), nitpicks: [], elevations: [] }, cross_model, resolveCommission);
    if (out) return out;
  }
  for (let keep = findings.length - 1; keep >= 0; keep--) {
    out = tryGrade({ ...base, findings: findings.slice(0, keep), nitpicks: [], elevations: [] }, cross_model, resolveCommission);
    if (out) return out;
  }
  // 4) minimal conformant output (reasoning+verdict only) — empty item arrays always conform
  out = tryGrade({ ...base, findings: [], nitpicks: [], elevations: [] }, cross_model, resolveCommission);
  if (out) return out;
  // Unreachable in practice (the empty shape is conformant); stay honest if a seam ever breaks it.
  throw new Error(`gandalf-host: could not salvage a conformant output (${firstLine})`);
}

export function writeRunRecord(record, { skillDir = resolve(dirname(fileURLToPath(import.meta.url)), '..') } = {}) {
  try {
    // Provenance discipline: capture is for REAL runs only. The test suite spawns
    // this CLI, and those children inherit NODE_TEST_CONTEXT — skip capture there
    // so mock runs never pollute the training feed (same rule as tidy-idy).
    if (process.env.NODE_TEST_CONTEXT) return null;
    const dir = join(skillDir, 'journal', 'runs');
    mkdirSync(dir, { recursive: true });
    const started = record.started || new Date().toISOString();
    const id = `${started.replace(/[:.]/g, '-')}-${Math.abs(Date.now() % 100000)}`;
    const file = join(dir, `${id}.json`);
    writeFileSync(file, JSON.stringify({ skill: 'gandalf', ...record }, null, 2) + '\n', 'utf8');
    return file;
  } catch {
    return null; // capture is best-effort by design
  }
}

export function decideTier({
  payload,
  objective = '',
  env = process.env,
  projectDir = null,
  highContextLimit = null,
  maxChunkBytes = null
} = {}) {
  const limit = resolveHighContextLimit(env, highContextLimit);
  const chunkCeiling = resolveMaxChunkBytes(env, maxChunkBytes);

  const tokens = estimatePayloadTokens(payload, projectDir);
  const bytes = estimateSerializedSize(payload, projectDir);

  // Default: a scoped payload that fits is answered directly — no scaling up.
  if (tokens <= limit && bytes <= chunkCeiling) {
    return 'direct';
  }

  const wholeRepo = looksLikeWholeRepo(payload);
  const allowRepoScale = env.GANDALF_ALLOW_REPO_SCALE === '1';
  const skipScout = env.GANDALF_SKIP_SCOUT === 'true' || env.GANDALF_FORCE_WHOLE_REPO === 'true';

  // WHOLE-REPO GUARD: a whole-repo payload must be curated by the scout before any fan-out, and
  // the bulk fan-out itself requires an explicit opt-in. Without it, stay at 'scout'.
  if (wholeRepo && !allowRepoScale) {
    return 'scout';
  }

  // A scout bypass (or an opted-in whole-repo run) goes straight to the fan-out; otherwise the safe
  // default is still to scout-first and curate before deciding to fan out.
  if (skipScout) {
    return 'mapreduce';
  }
  return 'scout';
}

export async function runMapReduce({
  projectDir = null,
  payload,
  userObjective,
  agent = null,
  reduceAgent = null,
  env = process.env,
  log = () => {},
  highContextLimit = null,
  concurrencyLimit = 3,
  /** Band knobs from @foundry/triage gandalf table (optional). */
  maxShards = null,
  fusionPasses = null,
} = {}) {
  let activeAgent = agent;
  if (!activeAgent) {
    // W4 (2026-07-05): resolve the agy LABEL via the TRIO_TIER ladder — NEVER a hardcoded API-style id
    // (the old hardcoded default was a phantom id that live agy silently degrades to Flash). The clever
    // map=STANDARD / reduce=HEAVY split is applied by the CLI wiring (runtime/gandalf-run.mjs
    // runScaledAnalysis), which injects distinct map/reduce agents; standalone callers get one
    // ladder-resolved agent for both roles.
    const model = env.GANDALF_HIGH_CONTEXT_MODEL || env.GEMINI_MODEL || resolveGeminiModel({ env });
    const seam = makeGeminiCliSeam({ model, env, log });
    activeAgent = seam.agent;
  }
  // W4: the REDUCE/synthesis seat (and the single-frontier direct pass) may run on a distinct,
  // higher-tier agent than the bulk MAP reads. Defaults to activeAgent so standalone/legacy callers
  // (and every existing test that injects a single `agent`) behave exactly as before.
  const activeReduceAgent = reduceAgent || activeAgent;

  // Resolve High-Context + per-chunk byte limits (shared with decideTier so they never disagree).
  const limit = resolveHighContextLimit(env, highContextLimit);
  const maxChunkBytes = resolveMaxChunkBytes(env);

  // Resolve Concurrency limit
  let resolvedConcurrency = 3;
  if (env.GANDALF_MAX_CONCURRENCY) {
    const val = parseInt(env.GANDALF_MAX_CONCURRENCY, 10);
    if (!isNaN(val)) resolvedConcurrency = val;
  } else if (concurrencyLimit !== null && concurrencyLimit !== undefined) {
    resolvedConcurrency = concurrencyLimit;
  }

  const estimatedTokens = estimatePayloadTokens(payload, projectDir);
  const totalSerializedSize = estimateSerializedSize(payload, projectDir);

  // JUDGE SCOPE FIRST: default to a direct pass; only escalate when the scoped artifact warrants it.
  const tier = decideTier({ payload, objective: userObjective, env, projectDir, highContextLimit });

  if (tier === 'direct') {
    const resolvedPayload = resolvePayload(payload, projectDir);
    log(`Payload size (${estimatedTokens} tokens, ${totalSerializedSize} bytes) is within limits. Processing directly (tier=direct).`);
    const directPrompt = `Analyze the following files for the objective: "${userObjective}"

Codebase Payload:
${serializeChunk(resolvedPayload, projectDir)}

Provide a coherent advisory report addressing the user objective.`;

    // W4: a SMALL target answered in ONE frontier pass — the reduce (HEAVY/frontier) seat.
    const report = await activeReduceAgent(directPrompt, { label: 'map-reduce-direct' });
    return report;
  }

  log(`Payload size (${estimatedTokens} tokens, ${totalSerializedSize} bytes) exceeds limits. Checking scout-pass default.`);

  let scoutedPayload = payload;
  let degraded = false;
  let stamp = '';

  const skipScout = env.GANDALF_SKIP_SCOUT === 'true' || env.GANDALF_FORCE_WHOLE_REPO === 'true';

  if (!skipScout) {
    log(`Scouting first to filter the payload.`);
    scoutedPayload = await scoutAndFilter({
      projectDir,
      payload,
      userObjective,
      agent: activeAgent,
      env,
      log
    });

    if (isContentDropped(payload, scoutedPayload)) {
      degraded = true;
      const originalCount = getPayloadItemCount(payload);
      const prunedCount = getPayloadItemCount(scoutedPayload);
      const skippedCount = originalCount - prunedCount;
      stamp = `analyzed slice ${prunedCount} of ${originalCount}; skipped ${skippedCount}`;
      log(`Scouting dropped content. Stamp: "${stamp}"`);
    }
  } else {
    log(`Bypassing scout pass as requested.`);
  }

  const scoutedTokens = estimatePayloadTokens(scoutedPayload, projectDir);
  const scoutedSerializedSize = estimateSerializedSize(scoutedPayload, projectDir);

  if (scoutedTokens <= limit && scoutedSerializedSize <= maxChunkBytes) {
    const resolvedPayload = resolvePayload(scoutedPayload, projectDir);
    log(`Scouted payload size (${scoutedTokens} tokens, ${scoutedSerializedSize} bytes) is within limits. Processing directly.`);
    const directPrompt = `Analyze the following files for the objective: "${userObjective}"

Codebase Payload:
${serializeChunk(resolvedPayload, projectDir)}

Provide a coherent advisory report addressing the user objective.`;

    // W4: the final advisory over the curated (scouted) payload — the reduce (HEAVY/frontier) seat.
    let report = await activeReduceAgent(directPrompt, { label: 'map-reduce-direct' });
    if (degraded) {
      report = report + `\n\n[degraded:true] Stamp: ${stamp}`;
      const reportStr = new String(report);
      reportStr.degraded = true;
      reportStr.stamp = stamp;
      return reportStr;
    }
    return report;
  }

  // WHOLE-REPO GUARD: scouting could not curate this below whole-repo scale. Do NOT silently fan out
  // the whole repo for a focused question — that requires an explicit operator opt-in. Without it,
  // run a bounded, honestly-degraded direct pass over the slice that fits the per-chunk ceiling.
  const allowRepoScale = env.GANDALF_ALLOW_REPO_SCALE === '1';
  if (looksLikeWholeRepo(scoutedPayload) && !allowRepoScale) {
    const { kept, total, keptCount } = capPayloadToBudget(scoutedPayload, maxChunkBytes, projectDir);
    const skippedCount = total - keptCount;
    log(`Whole-repo guard: ${total} files exceed limits and GANDALF_ALLOW_REPO_SCALE!=1. Capping to ${keptCount} files and running a degraded direct pass instead of a Map-Reduce fan-out.`);
    const resolvedPayload = resolvePayload(kept, projectDir);
    const directPrompt = `Analyze the following files for the objective: "${userObjective}"

Codebase Payload:
${serializeChunk(resolvedPayload, projectDir)}

Provide a coherent advisory report addressing the user objective.`;

    // W4: the bounded degraded pass over the fitting slice — the reduce (HEAVY/frontier) seat.
    let report = await activeReduceAgent(directPrompt, { label: 'map-reduce-direct' });
    // Compose an honest degraded stamp (preserving any earlier scout-drop count in the total).
    const guardStamp = `analyzed slice ${keptCount} of ${total}; skipped ${skippedCount} (whole-repo fan-out gated; set GANDALF_ALLOW_REPO_SCALE=1 to opt in)`;
    const finalStamp = degraded && stamp ? `${stamp}; ${guardStamp}` : guardStamp;
    report = report + `\n\n[degraded:true] Stamp: ${finalStamp}`;
    const reportStr = new String(report);
    reportStr.degraded = true;
    reportStr.stamp = finalStamp;
    return reportStr;
  }

  log(`Payload size (${scoutedTokens} tokens, ${scoutedSerializedSize} bytes) exceeds limits. Initiating Map-Reduce.`);

  let groups = groupPayloadByTopLevelDir(scoutedPayload);
  // Band-thin + legacy env cap (L2/L4):
  // - locked call sites pass maxShards = knobs.shards; GANDALF_MAX_SHARDS may only TIGHTEN
  //   (min), never expand past the lock.
  // - unlocked call sites leave maxShards null; GANDALF_MAX_SHARDS is the legacy-only cap.
  let shardCap = null;
  if (maxShards != null && Number.isFinite(Number(maxShards))) {
    shardCap = Math.max(1, Math.floor(Number(maxShards)));
    if (env.GANDALF_MAX_SHARDS) {
      const envCap = Math.max(1, parseInt(env.GANDALF_MAX_SHARDS, 10) || 8);
      if (Number.isFinite(envCap)) shardCap = Math.min(shardCap, envCap);
    }
  } else if (env.GANDALF_MAX_SHARDS) {
    shardCap = Math.max(1, parseInt(env.GANDALF_MAX_SHARDS, 10) || 8);
  }
  if (shardCap != null) {
    const before = Object.keys(groups).length;
    groups = capGroupsToMaxShards(groups, shardCap);
    const after = Object.keys(groups).length;
    if (after < before) log(`band-thin: capped shards ${before} → ${after} (maxShards=${shardCap})`);
  }
  const groupEntries = Object.entries(groups);

  let activeCount = 0;
  let maxActiveCount = 0;

  const tasks = groupEntries.map(([groupName, chunk]) => {
    return async () => {
      activeCount++;
      if (activeCount > maxActiveCount) {
        maxActiveCount = activeCount;
      }
      log(`Starting chunk analysis for ${groupName} (current active: ${activeCount}, max active: ${maxActiveCount})`);

      try {
        const resultText = await mapOrSplit({
          payload: chunk,
          groupName,
          userObjective,
          activeAgent,
          reduceAgent: activeReduceAgent,
          maxChunkBytes,
          projectDir,
          log
        });
        return { group: groupName, text: resultText };
      } finally {
        activeCount--;
        log(`Finished chunk analysis for ${groupName} (current active: ${activeCount})`);
      }
    };
  });

  let chunkSummaries = await limitConcurrency(tasks, resolvedConcurrency);

  log(`Completed all ${chunkSummaries.length} chunk analyses (max concurrent tasks: ${maxActiveCount}). Initiating synthesis.`);

  const passes =
    fusionPasses != null && Number.isFinite(Number(fusionPasses))
      ? Math.max(1, Math.floor(Number(fusionPasses)))
      : 1;

  // fusionPasses > 1: hierarchical pair-fuse then final reduce (FULL band); LITE keeps one pass.
  if (passes >= 2 && chunkSummaries.length > 2) {
    log(`band-thin: fusionPasses=${passes} — intermediate pair fusion over ${chunkSummaries.length} shards`);
    const mid = [];
    for (let i = 0; i < chunkSummaries.length; i += 2) {
      const pair = chunkSummaries.slice(i, i + 2);
      if (pair.length === 1) {
        mid.push(pair[0]);
        continue;
      }
      const midPrompt = `You are a codebase synthesizer. Fuse these two chunk summaries.
User Objective: "${userObjective}"

${pair.map((s) => `--- Chunk: ${s.group} ---\n${s.text}`).join('\n\n')}

Return one fused summary.`;
      const text = await activeReduceAgent(midPrompt, { label: `map-reduce-fusion-mid-${i}` });
      mid.push({ group: `${pair[0].group}+${pair[1].group}`, text });
    }
    chunkSummaries = mid;
  }

  const synthPrompt = `You are a codebase synthesizer. You are given several chunk summaries of a codebase analysis.
User Objective: "${userObjective}"

Chunk Summaries:
${chunkSummaries.map(s => `--- Chunk: ${s.group} ---\n${s.text}`).join('\n\n')}

Please fuse these summaries into a single, coherent advisory report addressing the user objective.`;

  // W4: the top-level REDUCE — fuse the shard summaries on the HEAVY/frontier seat.
  const finalReport = await activeReduceAgent(synthPrompt, { label: 'map-reduce-synthesis' });
  if (degraded) {
    const reportWithStamp = finalReport + `\n\n[degraded:true] Stamp: ${stamp}`;
    const reportStr = new String(reportWithStamp);
    reportStr.degraded = true;
    reportStr.stamp = stamp;
    return reportStr;
  }
  return finalReport;
}

async function mapOrSplit({
  payload,
  groupName,
  userObjective,
  activeAgent,
  reduceAgent = null,
  maxChunkBytes,
  projectDir,
  log
}) {
  // W4: bulk MAP reads run on activeAgent (STANDARD); intra-shard SYNTHESIS on the reduce
  // (HEAVY/frontier) seat when supplied, else fall back to the single agent (legacy behaviour).
  const activeReduceAgent = reduceAgent || activeAgent;
  const items = getChunkItems(payload);

  const estimatedSize = estimateSerializedSize(items, projectDir);

  if (estimatedSize <= maxChunkBytes) {
    log(`Payload size (${estimatedSize} bytes) is within ceiling (${maxChunkBytes}). Mapping chunk: ${groupName}`);
    const serializedContent = serializeChunk(items, projectDir);
    const chunkPrompt = `Analyze the following files from directory/chunk: ${groupName}
User Objective: "${userObjective}"

Provide a summary of findings, code patterns, and potential issues for this chunk.

Codebase Chunk Files:
${serializedContent}`;

    return await activeAgent(chunkPrompt, { label: `map-reduce-chunk-${groupName}` });
  }

  log(`Payload size (${estimatedSize} bytes) exceeds ceiling (${maxChunkBytes}) for chunk ${groupName}. Splitting recursively.`);

  if (items.length > 1) {
    const mid = Math.floor(items.length / 2);
    const leftItems = items.slice(0, mid);
    const rightItems = items.slice(mid);

    log(`Splitting ${groupName} by file into two sub-chunks (sizes: ${leftItems.length}, ${rightItems.length})`);

    const leftName = `${groupName}.1`;
    const rightName = `${groupName}.2`;

    const leftSummary = await mapOrSplit({
      payload: leftItems,
      groupName: leftName,
      userObjective,
      activeAgent,
      reduceAgent: activeReduceAgent,
      maxChunkBytes,
      projectDir,
      log
    });

    const rightSummary = await mapOrSplit({
      payload: rightItems,
      groupName: rightName,
      userObjective,
      activeAgent,
      reduceAgent: activeReduceAgent,
      maxChunkBytes,
      projectDir,
      log
    });

    log(`Synthesizing split file summaries for ${groupName}`);
    const synthPrompt = `You are a codebase synthesizer. You are given several chunk summaries of a codebase analysis.
User Objective: "${userObjective}"

Chunk Summaries:
--- Chunk: ${leftName} ---
${leftSummary}

--- Chunk: ${rightName} ---
${rightSummary}

Please fuse these summaries into a single, coherent advisory report addressing the user objective.`;

    return await activeReduceAgent(synthPrompt, { label: `map-reduce-synth-${groupName}` });
  } else {
    const item = items[0];
    let filePath = '';
    let content = '';

    if (typeof item === 'string') {
      filePath = item;
      try {
        const fullPath = projectDir ? path.resolve(projectDir, filePath) : path.resolve(filePath);
        content = fs.readFileSync(fullPath, 'utf8');
      } catch {
        // fallback
      }
    } else if (item && typeof item === 'object') {
      filePath = item.path;
      if (item.content !== undefined) {
        content = item.content;
      } else {
        try {
          const fullPath = projectDir ? path.resolve(projectDir, filePath) : path.resolve(filePath);
          content = fs.readFileSync(fullPath, 'utf8');
        } catch {
          // fallback
        }
      }
    }

    const lines = content.split(/\r?\n/);
    if (lines.length <= 1) {
      log(`Warning: single line in ${filePath} exceeds ceiling. Mapping as-is.`);
      const serializedContent = serializeChunk(items, projectDir);
      const chunkPrompt = `Analyze the following files from directory/chunk: ${groupName}
User Objective: "${userObjective}"

Provide a summary of findings, code patterns, and potential issues for this chunk.

Codebase Chunk Files:
${serializedContent}`;

      return await activeAgent(chunkPrompt, { label: `map-reduce-chunk-${groupName}` });
    }

    const mid = Math.floor(lines.length / 2);
    const leftLines = lines.slice(0, mid);
    const rightLines = lines.slice(mid);

    log(`Splitting file ${filePath} by line into two halves (${leftLines.length} lines, ${rightLines.length} lines)`);

    const leftItem = {
      path: filePath,
      content: leftLines.join('\n')
    };
    const rightItem = {
      path: filePath,
      content: rightLines.join('\n')
    };

    const leftName = `${groupName}.1`;
    const rightName = `${groupName}.2`;

    const leftSummary = await mapOrSplit({
      payload: [leftItem],
      groupName: leftName,
      userObjective,
      activeAgent,
      reduceAgent: activeReduceAgent,
      maxChunkBytes,
      projectDir,
      log
    });

    const rightSummary = await mapOrSplit({
      payload: [rightItem],
      groupName: rightName,
      userObjective,
      activeAgent,
      reduceAgent: activeReduceAgent,
      maxChunkBytes,
      projectDir,
      log
    });

    log(`Synthesizing split line summaries for ${groupName}`);
    const synthPrompt = `You are a codebase synthesizer. You are given several chunk summaries of a codebase analysis.
User Objective: "${userObjective}"

Chunk Summaries:
--- Chunk: ${leftName} ---
${leftSummary}

--- Chunk: ${rightName} ---
${rightSummary}

Please fuse these summaries into a single, coherent advisory report addressing the user objective.`;

    return await activeReduceAgent(synthPrompt, { label: `map-reduce-synth-${groupName}` });
  }
}

export async function limitConcurrency(tasks, limit) {
  let resolvedLimit = 3;
  if (process.env.GANDALF_MAX_CONCURRENCY) {
    const val = parseInt(process.env.GANDALF_MAX_CONCURRENCY, 10);
    if (!isNaN(val)) resolvedLimit = val;
  } else if (typeof limit === 'number') {
    resolvedLimit = limit;
  }
  resolvedLimit = Math.max(1, resolvedLimit);

  const results = [];
  const executing = new Set();
  for (const task of tasks) {
    const p = Promise.resolve().then(() => task());
    results.push(p);
    executing.add(p);
    const clean = () => executing.delete(p);
    p.then(clean, clean);
    if (executing.size >= resolvedLimit) {
      await Promise.race(executing);
    }
  }
  return Promise.all(results);
}

export async function acquireSlot(lockDir, maxConcurrency, { timeoutMs } = {}) {
  const slots = Math.max(1, parseInt(maxConcurrency, 10) || 1);
  const envTimeout = parseInt(process.env.GANDALF_LOCK_TIMEOUT_MS, 10);
  const deadline = Date.now() + (timeoutMs ?? (Number.isNaN(envTimeout) ? DEFAULT_LOCK_TIMEOUT_MS : envTimeout));
  fs.mkdirSync(lockDir, { recursive: true });

  for (;;) {
    for (let slot = 0; slot < slots; slot++) {
      const slotDir = slotDirPath(lockDir, slot);
      try {
        fs.mkdirSync(slotDir);
      } catch (err) {
        if (err.code !== 'EEXIST') throw err;
        reclaimIfStale(slotDir); // dead owner → freed; a live contender retries it next pass
        continue;
      }
      fs.writeFileSync(path.join(slotDir, 'owner.json'), JSON.stringify({ pid: process.pid, acquired_at: new Date().toISOString() }));
      return slot;
    }
    if (Date.now() >= deadline) {
      throw new Error(`acquireSlot: timed out waiting for one of ${slots} slot(s) under ${lockDir}`);
    }
    await new Promise(resolve => setTimeout(resolve, SLOT_POLL_MS));
  }
}

export async function runScoutPass({
  projectDir,
  userObjective,
  agent = null,
  env = process.env,
  log = () => {}
} = {}) {
  try {
    const treeText = generateTreeText(projectDir);

    let activeAgent = agent;
    if (!activeAgent) {
      // W4 (2026-07-05): the scout is a lightweight, high-volume curation pass — it reads a whole tree
      // to pick relevant paths — so it runs on the STANDARD (current, cheaper, high-context) agy LABEL,
      // resolved via the TRIO_TIER ladder. NEVER a hardcoded API-style id (the old hardcoded default
      // was a phantom id that live agy silently degrades to Flash anyway).
      const model = env.GANDALF_SCOUT_MODEL || env.GEMINI_MODEL
        || resolveGeminiModel({ env: { ...env, TRIO_TIER: 'standard' } });
      const seam = makeGeminiCliSeam({ model, env, log });
      activeAgent = seam.agent;
    }

    const prompt = `You are an agentic codebase scout. You are given a directory tree structure of a codebase and the user's objective.
Your task is to identify and return a list of files or directories that are semantically relevant to the user's objective and should be included in the context.

User Objective:
"${userObjective}"

Codebase Directory Tree:
\`\`\`
${treeText}
\`\`\`

Respond with a JSON object containing an "include" key with an array of relative paths (files or directories) to include.`;

    const schema = {
      type: 'object',
      properties: {
        include: {
          type: 'array',
          items: { type: 'string' }
        }
      },
      required: ['include']
    };

    const result = await activeAgent(prompt, { schema, label: 'scout-pass' });
    let includeList = null;

    if (typeof result === 'object' && result !== null) {
      includeList = result.include;
    } else if (typeof result === 'string') {
      const parsed = JSON.parse(result);
      includeList = parsed.include;
    }

    if (Array.isArray(includeList)) {
      return includeList;
    }
    throw new Error('Scout model response did not contain an array under the "include" key.');
  } catch (err) {
    log(`Scout pass error: ${err.message}`);
    return null;
  }
}

export async function scoutAndFilter({
  projectDir,
  payload,
  userObjective,
  agent = null,
  env = process.env,
  log = () => {}
} = {}) {
  const includeList = await runScoutPass({ projectDir, userObjective, agent, env, log });
  if (includeList === null) {
    log('Scout pass failed or returned malformed data. Gracefully falling back to full payload.');
    return payload;
  }
  return prunePayload(payload, includeList);
}

export async function runLiveRefutation(rawDraft, {
  agent,
  ledger,
  routes = null,
  drafterFamily = DRAFTER_FAMILY,
  refuterFamily = REFUTER_FAMILY,
  budget = REFUTER_BUDGET_R,
  refutePrompt = defaultRefutePrompt,
  role = 'refuter',
  log = () => {},
} = {}) {
  if (!isPlainObject(rawDraft)) {
    throw new TypeError('runLiveRefutation: rawDraft must be a plain object');
  }
  if (!ledger || typeof ledger.mintCommission !== 'function' || typeof ledger.resolveCommission !== 'function') {
    throw new TypeError('runLiveRefutation: a shared commission ledger { mintCommission, resolveCommission } is required (invariant 1)');
  }
  if (typeof agent !== 'function') {
    throw new TypeError('runLiveRefutation: an injected role-routed agent(prompt, opts) is required');
  }
  // INVARIANT 3 — routing guard: a refuter role must resolve to a NON-drafter family (never self-review).
  if (routes) assertCrossFamilyRouting({ routes, drafterFamily });

  const rawElevations = Array.isArray(rawDraft.elevations) ? rawDraft.elevations : [];

  // Which elevations FIRE the refuter (value-if-true ≥ HIGH OR severity ≥ major).
  const firing = [];
  rawElevations.forEach((e, i) => { if (isPlainObject(e) && firesRefuter(e)) firing.push(i); });
  // INVARIANT 5, revised 2026-08-25 (John's ruling — elegance card + cost amendment; journals
  // 0296/0298-0301: the frozen R=3 HALT fired on nearly every real read, was twice misread as
  // "agy down", and shipped two avoidably-degraded deliverables). Cost is a PRE-FLIGHT
  // conversation, never a mid-run wall: excess firing elevations no longer HALT the run — the
  // top-R by value/severity get refuters; the excess ships UN-REFUTED and floors to SPECULATIVE
  // by the existing honest-floor invariant, each named in the dispatch log. Nothing is silently
  // dropped; paid-for output is never withheld (Gandalf's own locked law). The runaway ceiling
  // (>4×R) also finishes-and-stamps — it only escalates the log line.
  let toRefute = firing;
  let floored = [];
  if (firing.length > budget) {
    const rank = (i) => {
      const e = rawElevations[i];
      const v = String(e?.value_if_true ?? '').toLowerCase() === 'high' ? 2 : 1;
      // 2026-08-25 review fix: 'critical' outranks 'major' (it scored 0 — criticals
      // were floored BEFORE majors under budget pressure, inverted priority).
      const sev = String(e?.severity ?? '').toLowerCase();
      const s = sev === 'critical' ? 2 : sev === 'major' ? 1 : 0;
      return v * 10 + s;
    };
    const sorted = [...firing].sort((a, b) => rank(b) - rank(a) || a - b);
    toRefute = sorted.slice(0, budget).sort((a, b) => a - b);
    floored = sorted.slice(budget).sort((a, b) => a - b);
    const nameOf = (i) => rawElevations[i]?.id ?? `e${i}`;
    const ceiling = firing.length > Math.max(12, 4 * budget) ? ' RUNAWAY CEILING TRIPPED —' : '';
    log(`refuter budget PRE-FLIGHT:${ceiling} ${firing.length} firing elevation(s) exceed budget ${budget} — FLOORING, not halting: refuting top ${budget} (${toRefute.map(nameOf).join(', ')}); ${floored.length} ship SPECULATIVE un-refuted (${floored.map(nameOf).join(', ')}). Re-run with --budget ${firing.length} to cover all.`);
  }
  const firingSet = new Set(toRefute);
  const flooredSet = new Set(floored);

  // B3 (2026-07-11): firing elevations are INDEPENDENT — each gets its own refuter
  // call, its own mint, its own provenance — so they dispatch CONCURRENTLY under a
  // bounded cap instead of the old for-await serialization (which made the refuter
  // leg the second-longest stage of every real run: N × tens of seconds, serial).
  // Cap default 2 (agy OOMs above ~3 concurrent — the crucible/researchPrime caps
  // encode the same host fact); GANDALF_REFUTER_CONCURRENCY overrides, ceiling 3.
  // Determinism: results are placed by INDEX, dispatch is sorted by index, and the
  // ledger mints in-process — output is order-independent of completion order.
  const capEnv = Number(process.env.GANDALF_REFUTER_CONCURRENCY);
  const cap = Math.min(3, Number.isFinite(capEnv) && capEnv > 0 ? capEnv : 2);

  const refuteOne = async (i) => {
    const raw = rawElevations[i];
    // INVARIANT 2 — the object the GATE will read. We mint on THIS exact object and place it in the
    // returned draft, so elevationIdentity(bound) at mint === elevationIdentity(bound) at the gate.
    const bound = { ...raw };
    const label = `refuter:${raw.id ?? `e${i}`}`;
    try {
      const reply = await agent(refutePrompt(raw), { role, label, schema: REFUTER_REPLY_SCHEMA });
      const { defeater, survived, verdict } = extractRefuterVerdict(reply);

      // INVARIANT 4 — survived must be an EXPLICIT boolean and defeater a NAMED concrete defeater;
      // anything else ⇒ NO provenance ⇒ the host floors the elevation to SPECULATIVE (honest floor).
      if (typeof survived !== 'boolean' || !isNamedDefeater(defeater)) {
        return { index: i, bound, entry: { index: i, id: raw.id ?? null, minted: false, reason: 'refuter returned no explicit survived boolean and/or no named concrete defeater' } };
      }

      const v = (verdict === undefined || verdict === null || verdict === '') ? null : String(verdict);
      // The digest the commission is bound to — computed over THIS bound elevation's identity + the
      // refuter content. composeRefutationProvenance recomputes the SAME digest from the SAME args
      // (field parity: {defeater, survived, verdict} hashed == what the envelope stores), so the ledger
      // tuple's result_digest === the provenance's result_digest === the gate's recomputed digest.
      const result_digest = computeResultDigest({ elevation: bound, defeater, survived, verdict: v });
      const commission_id = ledger.mintCommission({
        drafter_family: drafterFamily,
        refuter_family: refuterFamily,
        result_digest,
      });
      const provenance = composeRefutationProvenance({
        elevation: bound,
        defeater,
        survived,
        verdict: v,
        drafter_family: drafterFamily,
        refuter_family: refuterFamily,
        commission_id,
      });
      bound.refutation_provenance = provenance;

      if (survived === false) {
        // The named defeater LANDED — the claim is refuted. Only-REFUTED-drops: the host will drop it.
        bound.rung = 'REFUTED';
      } else {
        // A surviving, cross-family refutation REQUESTS the GROUNDED tier; the gate (derived cross_family
        // eligibility from the shared ledger) is the sole authority that grants or caps it.
        bound.tier = 'GROUNDED';
      }
      return { index: i, bound, entry: { index: i, id: raw.id ?? null, minted: true, survived, commission_id } };
    } catch (err) {
      // INVARIANT 4 (honest-HALT): the refuter errored / agy is down (W0 seam throws HaltError on a
      // non-attested / substituted rec) / empty reply. The elevation gets NO provenance ⇒ SPECULATIVE ⇒
      // cross_model NOT lifted. We NEVER fabricate a survived:true to manufacture a cross-family grant.
      log(`!! ${label}: refuter failed (${err?.message ?? err}) — elevation stays SPECULATIVE (no provenance minted)`);
      return { index: i, bound, entry: { index: i, id: raw.id ?? null, minted: false, reason: `refuter failed: ${err?.message ?? err}` } };
    }
  };

  // Bounded pool: `cap` workers drain the firing queue; per-elevation failures are
  // handled INSIDE refuteOne (it never rejects), so one bad refuter cannot sink the batch.
  const queue = [...toRefute];
  const results = new Map(); // index -> { bound, entry }
  await Promise.all(Array.from({ length: Math.min(cap, queue.length) }, async () => {
    while (queue.length) {
      const i = queue.shift();
      const r = await refuteOne(i);
      results.set(r.index, r);
    }
  }));

  const outElevations = [];
  const dispatch = [];
  for (let i = 0; i < rawElevations.length; i++) {
    const raw = rawElevations[i];
    if (!isPlainObject(raw)) { outElevations.push(raw); continue; }
    // Budget-floored elevations: fired but not refuted this run — recorded, never silent.
    if (flooredSet.has(i)) {
      outElevations.push({ ...raw });
      dispatch.push({ index: i, id: raw.id ?? null, minted: false, reason: `budget floor (pre-flight): fired but not refuted this run — ships SPECULATIVE; re-run with --budget ${firing.length} to cover` });
      continue;
    }
    // Below-threshold elevations earn no refuter — pass a fresh copy through (the host floors them).
    if (!firingSet.has(i)) { outElevations.push({ ...raw }); continue; }
    const r = results.get(i);
    outElevations.push(r.bound);
    dispatch.push(r.entry);
  }

  return { draft: { ...rawDraft, elevations: outElevations }, dispatch };
}

export async function buildLiveRefuterAgent({ routes, drafterFamily, env = process.env } = {}) {
  const { makeRoleRoutedAgent, buildRoutesFromFamilies, familyToDriverName } = await import('file:///C:/dev/trio/drivers/index.mjs');
  const built = buildRoutesFromFamilies({
    env,
    codingRoles: [],
    reviewRoles: ['refuter'],
  });
  const resolvedDrafter = resolveDrafterFamily({ drafterFamily, env, codingFamily: built.families?.coding });
  let resolvedRoutes = routes;
  if (!resolvedRoutes) {
    // (2026-09-04) refuter = the configured non-drafter family; review_family first.
    const fam = pickRefuterFamily({ families: built.families || {}, drafterFamily: resolvedDrafter });
    const drv = fam ? familyToDriverName(fam) : null;
    resolvedRoutes = drv ? { ...built.routes, refuter: { driver: drv } } : built.routes;
  }
  // Fail-closed: a refuter that resolves to the drafter's family is a self-refutation HALT.
  assertCrossFamilyRouting({ routes: resolvedRoutes, drafterFamily: resolvedDrafter });
  return makeRoleRoutedAgent({ routes: resolvedRoutes, env: { ...env, CRUCIBLE_AGENT_LIVE: '1' } });
}

export function resolveDrafterFamily({ drafterFamily, env = process.env, codingFamily } = {}) {
  const pick = (v) => (typeof v === 'string' && v.trim() ? v.trim().toLowerCase() : null);
  return pick(drafterFamily) || pick(env.GANDALF_DRAFTER_FAMILY) || (env.CLAUDECODE ? 'claude' : null) || pick(codingFamily) || DRAFTER_FAMILY;
}

export function pickRefuterFamily({ families = {}, drafterFamily } = {}) {
  const d = String(drafterFamily || '').toLowerCase();
  for (const f of [families.review, families.coding]) {
    const fam = String(f || '').toLowerCase();
    if (fam && fam !== d) return fam;
  }
  return null;
}

export function assertCrossFamilyRouting({ routes = {}, drafterFamily = DRAFTER_FAMILY } = {}) {
  const route = (routes && (routes.refuter || routes.default)) || {};
  const driver = route.driver || null;
  const refuterFamily = familyFromDriver(driver);
  const drafter = String(drafterFamily ?? '').trim().toLowerCase();
  if (!refuterFamily || refuterFamily === drafter) {
    throw new SelfRefutationHalt(refuterFamily, drafter, driver);
  }
  return refuterFamily;
}

export function firesRefuter(item) {
  if (item === null || typeof item !== 'object') return false;
  const vFloor = VALUE_LADDER.indexOf(REFUTER_FIRING_THRESHOLD.value_if_true_at_least);
  const sFloor = SEVERITY_LADDER.indexOf(REFUTER_FIRING_THRESHOLD.or_severity_at_least);
  const vIdx = VALUE_LADDER.indexOf(item.value_if_true);
  const sIdx = SEVERITY_LADDER.indexOf(item.severity);
  const valueFires = vIdx !== -1 && vFloor !== -1 && vIdx >= vFloor;
  const severityFires = sIdx !== -1 && sFloor !== -1 && sIdx >= sFloor;
  return valueFires || severityFires;
}

export function isCrossFamilyRefutation(elevation, resolveCommission = NOOP_COMMISSION_VERIFIER) {
  if (elevation === null || typeof elevation !== 'object' || Array.isArray(elevation)) return false;
  const prov = elevation.refutation_provenance;
  if (prov === null || typeof prov !== 'object' || Array.isArray(prov)) return false;
  // The commission-id the orchestrator minted for this refutation (accept either envelope spelling).
  const id = isNonEmptyString(prov.refuter_commission_id)
    ? prov.refuter_commission_id
    : (isNonEmptyString(prov.commission_id) ? prov.commission_id : null);
  if (id === null) return false;
  let resolved;
  try {
    resolved = typeof resolveCommission === 'function' ? resolveCommission(id) : null;
  } catch {
    return false; // a resolver that throws is a non-resolution — never a cross-family grant
  }
  // (a) AUTHENTIC — the ledger returned a well-formed tuple for this id.
  if (resolved === null || typeof resolved !== 'object' || Array.isArray(resolved)) return false;
  if (!isNonEmptyString(resolved.drafter_family) || !isNonEmptyString(resolved.refuter_family)) return false;
  // (b) FAMILY-DISTINCT — drafter and refuter are different model families.
  if (resolved.drafter_family === resolved.refuter_family) return false;
  // (c) DIGEST-MATCHED — the ledger's digest binds THIS refutation's actual content AND THIS elevation's
  //     identity (recomputed here; never a stored/self-reported digest). Passing `elevation` claim-binds
  //     the digest: a provenance minted for elevation A, copied onto elevation B, recomputes over B's
  //     identity (id + reasoning + named defeater) ⇒ mismatches the ledger tuple ⇒ the replay is rejected.
  const recomputed = computeResultDigest({
    elevation,
    defeater: prov.defeater,
    survived: prov.survived,
    verdict: prov.verdict ?? null,
  });
  if (resolved.result_digest !== recomputed) return false;
  return true;
}

export function assertRefuterBudget(requested, R = REFUTER_BUDGET_R) {
  if (!Number.isInteger(requested) || requested < 0) {
    throw new Error(`refute: assertRefuterBudget requires a non-negative integer count, got ${JSON.stringify(requested)}`);
  }
  if (requested > R) throw new RefuterBudgetHalt(requested, R);
  return requested;
}

export function createCommissionLedger({ secret } = {}) {
  let runSecret =
    secret != null
      ? Buffer.from(secret instanceof Buffer ? secret : String(secret), 'utf8')
      : crypto.randomBytes(32);
  const issued = new Set(); // ids minted by THIS ledger this run

  /**
   * Mint a commission-id CRYPTOGRAPHICALLY BOUND to (drafter_family, refuter_family, result_digest).
   * The id = `gcl1.base64url(canonicalTuple).HMAC-SHA256(secret, canonicalTuple)` — it cannot be
   * fabricated for a tuple without the mint's secret. Throws on a malformed tuple (never mints a
   * partial/forgeable id).
   *
   * @param {{drafter_family:string, refuter_family:string, result_digest:string}} tuple
   * @returns {string} the minted commission-id
   */
  function mintCommission({ drafter_family, refuter_family, result_digest } = {}) {
    const tuple = { drafter_family, refuter_family, result_digest };
    if (!isWellFormedTuple(tuple)) {
      throw new Error(
        'commission-ledger: mintCommission requires non-empty drafter_family, refuter_family, and result_digest strings'
      );
    }
    const payload = canonicalCommissionTuple(tuple);
    const mac = hmacHex(runSecret, payload);
    const id = `${COMMISSION_ID_PREFIX}${SEP}${b64urlEncode(payload)}${SEP}${mac}`;
    issued.add(id);
    return id;
  }

  /**
   * Resolve a commission-id to the tuple it is bound to, or `null` for any id this ledger did not
   * authentically mint. Returns null when the id is: not a string / wrong prefix / malformed; carries a
   * signature that does not re-derive from its embedded tuple (a forged or TAMPERED id — e.g. a swapped
   * result_digest); or was not minted by THIS ledger this run (a random or cross-run/cross-secret id).
   *
   * @param {string} id
   * @returns {{drafter_family:string, refuter_family:string, result_digest:string} | null}
   */
  function resolveCommission(id) {
    if (typeof id !== 'string' || id.length === 0) return null;
    const parts = id.split(SEP);
    if (parts.length !== 3 || parts[0] !== COMMISSION_ID_PREFIX) return null;
    let payload;
    try {
      payload = b64urlDecode(parts[1]);
    } catch {
      return null;
    }
    // (1) CONTENT-BINDING: re-derive the HMAC over the presented tuple bytes. A forged id or a tampered
    //     tuple (any field changed) yields a different signature and fails here.
    const expectedMac = hmacHex(runSecret, payload);
    if (!timingSafeHexEqual(expectedMac, parts[2])) return null;
    // (2) MINTED-THIS-RUN: it must have actually been minted by THIS ledger (orchestrator-minted,
    //     resolvable). An id from another run/secret is rejected even if otherwise well-formed.
    if (!issued.has(id)) return null;
    let tuple;
    try {
      tuple = JSON.parse(payload);
    } catch {
      return null;
    }
    if (!isWellFormedTuple(tuple)) return null;
    return {
      drafter_family: tuple.drafter_family,
      refuter_family: tuple.refuter_family,
      result_digest: tuple.result_digest,
    };
  }

  /** Predicate: was `id` minted by THIS ledger this run? Pure; never throws. */
  function isMinted(id) {
    return typeof id === 'string' && issued.has(id);
  }

  /** The number of ids minted by this ledger this run. */
  function size() {
    return issued.size;
  }

  /** Reset the ledger for reuse across runs: clear the minted-this-run membership AND rotate the
   *  per-run secret. After reset(), every previously-minted id resolves to null (its signature no
   *  longer re-derives under the new secret AND it is no longer in `issued`) — a clean per-run state
   *  with no leak from the prior run. Pure side-effect on this closure; returns nothing. */
  function reset() {
    issued.clear();
    runSecret = crypto.randomBytes(32);
  }

  return { mintCommission, resolveCommission, isMinted, size, reset };
}

export function applySeamPass(rawDraft, { cross_model = false, resolveCommission } = {}) {
  validateRawDraft(rawDraft);
  const crossModelRequested = cross_model === true; // the caller INTENT — never the stamp itself
  // A FRESH per-run ledger (no module-default singleton state leak). The injection seam wins: tests and
  // future callers may pass an explicit resolver; otherwise this run resolves against its own ledger.
  const resolve = typeof resolveCommission === 'function'
    ? resolveCommission
    : createCommissionLedger().resolveCommission;

  // The three item arrays are coerced to [] when the model omitted them (lenient input).
  const rawFindings = Array.isArray(rawDraft.findings) ? rawDraft.findings : [];
  const rawNitpicks = Array.isArray(rawDraft.nitpicks) ? rawDraft.nitpicks : [];
  const rawElevations = Array.isArray(rawDraft.elevations) ? rawDraft.elevations : [];

  // --- findings: dispatch by kind through the shipped seams; drop only REFUTED -----------------
  // 2026-08-25 (John-ratified card — journals 0301/0303: killed/dropped items left NO record,
  // so a kill was indistinguishable from a silent omission — an honesty hole in an honesty
  // engine): every drop is RECORDED with its reason in output.kill_log (below the fold).
  const killLog = { findings: [], nitpicks: [], elevations: [] };
  const briefOf = (raw) => String(raw?.topic ?? raw?.claim ?? raw?.message ?? raw?.id ?? '(untitled)').slice(0, 120);
  const findings = [];
  let anyDegraded = false;
  rawFindings.forEach((raw, i) => {
    if (!isPlainObject(raw)) { killLog.findings.push({ index: i, reason: 'not an object' }); return; }
    if (dropsFromOutput(raw)) { killLog.findings.push({ index: i, brief: briefOf(raw), reason: 'REFUTED — rung refuted by its refutation record' }); return; }
    const passed = passFinding(raw, i); // never throws now (a seam refusal → a generic finding)
    if (itemDegraded(passed)) anyDegraded = true;
    findings.push(ensureItemKeys(passed, i, 'f'));
  });

  // --- nitpicks: normalize to the required keys; skip non-objects; drop REFUTED -----------------
  const nitpicks = [];
  rawNitpicks.forEach((raw, i) => {
    if (!isPlainObject(raw)) { killLog.nitpicks.push({ index: i, reason: 'not an object' }); return; }
    if (dropsFromOutput(raw)) { killLog.nitpicks.push({ index: i, brief: briefOf(raw), reason: 'REFUTED — rung refuted by its refutation record' }); return; }
    if (itemDegraded(raw)) anyDegraded = true;
    nitpicks.push(ensureItemKeys(raw, i, 'n'));
  });

  // --- elevations: vet refutation (SPECULATIVE floor) → label tier; drop REFUTED ----------------
  const elevations = [];
  let anyCrossFamily = false; // W2b: DERIVES the top-level cross_model — set only by a genuine refutation
  rawElevations.forEach((raw, i) => {
    if (!isPlainObject(raw)) { killLog.elevations.push({ index: i, reason: 'not an object' }); return; }
    let passed;
    try {
      passed = passElevation(raw, i, resolve);
    } catch (e) {
      // an un-salvageable elevation is dropped, never fatal to the run — but RECORDED
      killLog.elevations.push({ index: i, brief: briefOf(raw), reason: `un-salvageable: ${e?.message ?? e}` });
      return;
    }
    if (passed === null) {
      // dropped (REFUTED) — record WHY, incl. the refutation's named defeater when present
      const defeater = raw?.refutation_provenance?.defeater ?? null;
      killLog.elevations.push({ index: i, brief: briefOf(raw), reason: 'REFUTED — the named defeater landed', defeater });
      return;
    }
    if (passed.cross_family_refuted === true) anyCrossFamily = true; // a real ledger-bound refutation
    if (itemDegraded(passed)) anyDegraded = true;
    // Guarantee a valid value_if_true (required enum) before normalizing the rest.
    if (!_VALUES.includes(passed.value_if_true)) passed = { ...passed, value_if_true: 'low' };
    elevations.push(ensureItemKeys(passed, i, 'e'));
  });

  // --- assemble the partial output, then synthesize honest risk_labels over it ------------------
  // B6: if any item ran degraded, OR the draft itself declared degraded, the top level owns it.
  const degraded = anyDegraded || rawDraft.degraded === true;

  // W2b: cross_model is DERIVED — true IFF a shipped elevation earned a genuine cross-family
  // refutation. The caller's intent flag is recorded separately and never sets this true.
  const output = {
    schema_version: SCHEMA_VERSION,
    cross_model: anyCrossFamily === true,
    cross_model_requested: crossModelRequested,
    degraded,
    reasoning: rawDraft.reasoning, // reasoning BEFORE verdict (key order is load-bearing)
    verdict: rawDraft.verdict,
    findings,
    nitpicks,
    elevations,
    risk_labels: [], // filled below from the finalized findings
  };
  // composeRiskLabels reads the finalized findings: one label per present leg, envelope rung,
  // PROMISING ceiling on a single-family run.
  output.risk_labels = composeRiskLabels(output);

  // Kill log rides below the fold (additive; schema additionalProperties:true) — John sees
  // WHY each recommendation died, and a kill is never confusable with a silent omission.
  output.kill_log = killLog;

  return output;
}

function passFinding(raw, index) {
  if (!isPlainObject(raw)) {
    throw new SeamPassInputError(`findings[${index}] is not an object`);
  }
  const kind = raw.kind;
  try {
    if (kind === 'diagnose') {
      // The vetted-core diagnosis keeps its rung; the seam appends gandalf_core provenance.
      return stampDiagnoseCoreProvenance(raw);
    }
    if (kind === 'anticipate') {
      // composeAnticipation enforces subject_cardinality:1 + a populated future-state + enabling
      // assumption (B3 + B9), and refuses any Oranges-engine field. It mints a FRESH finding from
      // the raw stages, so we pass the raw fields straight through.
      const composed = composeAnticipation({
        id: raw.id,
        future_state_condition: raw.future_state_condition,
        enabling_assumption: raw.enabling_assumption,
        reasoning: raw.reasoning,
        verdict: raw.verdict,
        rung: raw.rung ?? 'UNVERIFIED',
        severity: raw.severity,
      });
      // Preserve an honest per-item degraded flag the seam does not carry (B6 rolls it up).
      if (raw.degraded === true) composed.degraded = true;
      return composed;
    }
    if (kind === 'situate') {
      // composeSituate runs the SITUATE honesty caps (no self-CORROBORATED; unverifiable → handoff).
      // Tier-1 has no live researchPrime commission, so facts_verified is false by construction and
      // the seam attaches the needs_verification handoff itself.
      const composed = composeSituate({
        id: raw.id,
        abstraction: raw.abstraction,
        commission: raw.commission,
        structure_map: raw.structure_map,
        outside_view_base_rate: raw.outside_view_base_rate,
        reasoning: raw.reasoning,
        verdict: raw.verdict,
        facts_verified: false, // Tier-1: no independent commission ran ⇒ never self-verified
      });
      if (raw.degraded === true) composed.degraded = true;
      return composed;
    }
    // Any other finding kind (incl. a bare nitpick-shaped finding) passes through untouched — the
    // schema only gates diagnose/situate/anticipate provenance.
    return { ...raw };
  } catch (err) {
    if (err instanceof SeamPassInputError) throw err;
    // The seam refused this item (e.g. an anticipate finding missing its future-state, or a situate
    // finding missing its structure map) — a real model draft will sometimes do this. Don't fail the
    // whole run: PRESERVE the content as a GENERIC finding (strip the leg `kind` + any half-formed
    // provenance so no leg-specific canary applies); it is normalized to the required keys downstream.
    const { kind: _k, gandalf_core: _gc, ...generic } = raw;
    return generic;
  }
}

function validateRawDraft(rawDraft) {
  if (!isPlainObject(rawDraft)) {
    throw new SeamPassInputError('the raw draft must be a plain object (got ' + (rawDraft === null ? 'null' : Array.isArray(rawDraft) ? 'array' : typeof rawDraft) + ')');
  }
  if (!isNonEmptyString(rawDraft.reasoning)) {
    throw new SeamPassInputError("the raw draft must carry a non-empty 'reasoning' string (reasoning-before-verdict)");
  }
  if (!isNonEmptyString(rawDraft.verdict)) {
    throw new SeamPassInputError("the raw draft must carry a non-empty 'verdict' string");
  }
}

export function composeSituate({
  id,
  abstraction,
  commission,
  structure_map,
  outside_view_base_rate,
  reasoning,
  verdict,
  facts_verified = false,
} = {}) {
  if (!isNonEmptyString(id)) throw new Error('situate: composeSituate requires an id');
  if (!isNonEmpty(abstraction)) throw new Error('situate: composeSituate requires an S0 abstraction');
  if (commission === null || typeof commission !== 'object') {
    throw new Error('situate: composeSituate requires a researchPrime commission envelope');
  }
  if (!isWellFormedStructureMap(structure_map)) {
    throw new Error('situate: composeSituate requires a structure-map with ≥2 answer-first relational correspondences');
  }
  if (!isNonEmpty(outside_view_base_rate)) {
    throw new Error('situate: composeSituate requires an outside-view base rate');
  }

  const independent = independentOriginCredit(commission);
  const verified = facts_verified === true;
  // No self-CORROBORATED: only an independent-origin commission lifts the rung above the cap.
  const rung = independent && verified ? 'CORROBORATED' : SITUATE_SELF_MAX_RUNG;

  const finding = {
    id,
    kind: SITUATE_KIND,
    rung,
    reasoning: isNonEmptyString(reasoning) ? reasoning : `SITUATE: structure-mapped against ${commission.question}.`,
    verdict: isNonEmptyString(verdict) ? verdict : structure_map.answer,
    s0_abstraction: abstraction,
    researchprime_commission_id: commission.researchprime_commission_id ?? null,
    independent_origin: independent,
    structure_map,
    outside_view_base_rate,
    facts_verified: verified,
  };
  // Unverifiable facts are routed to a researchPrime verification handoff (never asserted real).
  if (!verified) {
    finding.needs_verification = `route to researchPrime: independently verify the structure-map correspondences and outside-view base rate for '${id}' (single-family substrate earns no independent-origin credit)`;
  }
  return finding;
}

export function commissionResearchPrime({ question, cross_model = false, commission_id = null } = {}) {
  if (!isNonEmptyString(question)) {
    throw new Error('situate: commissionResearchPrime requires a non-empty question');
  }
  const independent = cross_model === true;
  return {
    skill: 'researchPrime',
    question: question.trim(),
    cross_model: Boolean(cross_model),
    origin_family: PERSONA_FAMILY,
    independent_origin: independent,
    researchprime_commission_id: commission_id,
  };
}

export function composeRiskLabels(output) {
  const findings = Array.isArray(output?.findings) ? output.findings : [];
  return legsPresent(output).map((leg) => {
    const rung = legEnvelopeRung(output, leg);
    // PER-LEG cross-family eligibility — keyed off each finding's OWN derived `cross_family_refuted`,
    // never the global cross_model flag. Findings carry no commission provenance ⇒ this is always false
    // ⇒ findings legs never launder up to GROUNDED off an unrelated elevation's genuine refutation.
    const legCrossFamily = findings.some(
      (f) => f && typeof f === 'object' && f.kind === leg && f.cross_family_refuted === true
    );
    const label = { leg, tier: legCrossFamily ? 'GROUNDED' : TIER_CEILING_SINGLE_FAMILY };
    if (rung !== null) label.rung = rung;
    return label;
  });
}

export function resolveGandalfBand({
  depth = null,
  tier = null,
  intake = {},
  allowDefault = true,
  env = process.env,
} = {}) {
  const d = pickGandalfDepth({ depth, env });
  const t = pickGandalfTier({ tier, env });
  const hasLockInput = Boolean(d || t);

  const recommendation = recommendForSkill('gandalf', {
    ...intake,
    depth: d || undefined,
    tier: t || undefined,
  });

  if (hasLockInput || allowDefault) {
    try {
      const resolved = resolveSkillLock('gandalf', {
        inputs: intake,
        confirmedDepth: d || recommendation.depth,
        confirmedTier: t || recommendation.tier,
        decision: 'confirm',
        recommendation,
      });
      // Lock path: refuse thinning that zeros seats (L4/L5 safety floor).
      if (hasLockInput) assertGandalfSeatsFloor(resolved.knobs);
      return {
        knobs: resolved.knobs,
        lock: resolved.lock,
        recommendation,
        source: hasLockInput ? 'explicit' : 'recommend-confirm',
      };
    } catch (err) {
      // Fail-closed on lock input: never soft-pick advisory / invent FULL.
      if (hasLockInput || !allowDefault) throw err;
    }
  }

  // Last resort advisory knobs (not a lock) — stamped unlocked for honesty.
  const knobs = knobsForSkill('gandalf', recommendation.depth, recommendation.tier);
  return {
    knobs,
    lock: null,
    recommendation,
    source: 'advisory',
  };
}

gandalf: Object.freeze({
